import { createHash } from 'node:crypto';
import { GetObjectCommand, PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { env } from '../config/env.js';

export function createS3Client() {
  return new S3Client({
    region: env.AWS_REGION,
    ...(env.AWS_ENDPOINT_URL ? { endpoint: env.AWS_ENDPOINT_URL, forcePathStyle: true } : {}),
  });
}

export const sha256 = (buffer) => createHash('sha256').update(buffer).digest('hex');

/**
 * Artifact storage (07-security-licensing/storage-access.md). Keys are always generated by the
 * platform. `put` re-reads the object and compares SHA-256 before reporting success, so an
 * artifact is never marked ready on a corrupted upload.
 */
export function createArtifactStore({ client, bucket }) {
  async function get(key) {
    const res = await client.send(new GetObjectCommand({ Bucket: bucket, Key: key }));
    return Buffer.from(await res.Body.transformToByteArray());
  }

  return {
    get,

    /** @returns {Promise<{ sha256: string, size: number, verified: boolean }>} */
    async put(key, body, { contentType, contentEncoding } = {}) {
      const expected = sha256(body);
      await client.send(
        new PutObjectCommand({
          Bucket: bucket,
          Key: key,
          Body: body,
          ContentType: contentType,
          ...(contentEncoding ? { ContentEncoding: contentEncoding } : {}),
          ChecksumAlgorithm: 'SHA256',
        }),
      );
      const stored = await get(key);
      return { sha256: expected, size: body.length, verified: sha256(stored) === expected };
    },
  };
}
